ALTER TABLE public.avisos ADD COLUMN exige_confirmacao boolean NOT NULL DEFAULT false;
ALTER TABLE public.perfil_permissoes DROP CONSTRAINT perfil_permissoes_permissao_check;
ALTER TABLE public.perfil_permissoes ADD CONSTRAINT perfil_permissoes_permissao_check CHECK (permissao IN ('admin.usuarios','admin.perfis','avisos.publicar','avisos.gerenciar','avisos.insider','avisos.confirmacao','conteudo.editar','documentos.gerenciar','formularios.gerenciar','pendencias.liderados'));
CREATE TABLE public.avisos_confirmacoes (aviso_id uuid NOT NULL REFERENCES public.avisos(id) ON DELETE CASCADE, usuario_id uuid NOT NULL, confirmado_em timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(aviso_id,usuario_id));
GRANT SELECT ON public.avisos_confirmacoes TO authenticated;
GRANT ALL ON public.avisos_confirmacoes TO service_role;
ALTER TABLE public.avisos_confirmacoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Consulta propria confirmacao" ON public.avisos_confirmacoes FOR SELECT TO authenticated USING(usuario_id=auth.uid() AND public.is_active_user(auth.uid()));
CREATE OR REPLACE FUNCTION public.pode_enviar_como(_perfil_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT (public.tem_permissao('avisos.publicar') OR public.tem_permissao('avisos.confirmacao')) AND EXISTS(SELECT 1 FROM public.usuario_perfis up JOIN public.perfis p ON p.id=up.perfil_id WHERE up.usuario_id=auth.uid() AND p.id=_perfil_id AND p.ativo AND (p.sistema OR ((p.departamento_sp_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.departamentos_sincronizacao WHERE id AND ativada)) AND EXISTS(SELECT 1 FROM public.perfil_permissoes pp WHERE pp.perfil_id=p.id AND pp.permissao IN ('avisos.publicar','avisos.confirmacao'))))) $$;
CREATE OR REPLACE FUNCTION public.gere_aviso(_autor uuid,_perfil uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_active_user(auth.uid()) AND ((_autor=auth.uid() AND (public.tem_permissao('avisos.publicar') OR public.tem_permissao('avisos.confirmacao'))) OR public.tem_permissao('avisos.gerenciar') OR public.pode_enviar_como(_perfil)); $$;
CREATE OR REPLACE FUNCTION public.avisos_validar_confirmacao() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF TG_OP='UPDATE' AND OLD.publicar_em<=now() AND NEW.exige_confirmacao IS DISTINCT FROM OLD.exige_confirmacao THEN RAISE EXCEPTION 'A exigência de confirmação não pode mudar após a publicação'; END IF;
IF NEW.exige_confirmacao AND (TG_OP='INSERT' OR NEW.exige_confirmacao IS DISTINCT FROM OLD.exige_confirmacao) AND NOT public.tem_permissao('avisos.confirmacao') THEN RAISE EXCEPTION 'Sem permissão para avisos com confirmação de leitura'; END IF;
IF NEW.exige_confirmacao AND NEW.tipo<>'comum' THEN RAISE EXCEPTION 'Confirmação de leitura disponível apenas para avisos comuns'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER avisos_validar_confirmacao BEFORE INSERT OR UPDATE ON public.avisos FOR EACH ROW EXECUTE FUNCTION public.avisos_validar_confirmacao();
CREATE OR REPLACE FUNCTION public.aviso_disponivel(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_active_user(auth.uid()) AND EXISTS(SELECT 1 FROM public.avisos a WHERE a.id=_id AND (public.aviso_vigente(a.publicar_em,a.expira_em,a.arquivado_em) OR (a.exige_confirmacao AND a.publicar_em<=now() AND a.arquivado_em IS NULL AND NOT EXISTS(SELECT 1 FROM public.avisos_confirmacoes c WHERE c.aviso_id=a.id AND c.usuario_id=auth.uid())))); $$;
ALTER POLICY "Ativos leem avisos vigentes" ON public.avisos USING(public.aviso_disponivel(id) OR public.gere_aviso(autor_id,perfil_id));
CREATE OR REPLACE FUNCTION public.confirmar_leitura_aviso(_aviso_id uuid) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE confirmado timestamptz; BEGIN
IF NOT public.aviso_disponivel(_aviso_id) OR NOT EXISTS(SELECT 1 FROM public.avisos WHERE id=_aviso_id AND exige_confirmacao) THEN RAISE EXCEPTION 'Aviso indisponível para confirmação'; END IF;
INSERT INTO public.avisos_confirmacoes(aviso_id,usuario_id) VALUES(_aviso_id,auth.uid()) ON CONFLICT DO NOTHING;
SELECT confirmado_em INTO confirmado FROM public.avisos_confirmacoes WHERE aviso_id=_aviso_id AND usuario_id=auth.uid(); RETURN confirmado; END $$;
CREATE OR REPLACE FUNCTION public.listar_avisos_confirmacao(_so_nao_lidos boolean DEFAULT false,_limite integer DEFAULT 20,_deslocamento integer DEFAULT 0,_so_obrigatorios boolean DEFAULT false,_aviso_id uuid DEFAULT null,_priorizar boolean DEFAULT false)
RETURNS TABLE(id uuid,titulo text,mensagem text,perfil_nome text,publicar_em timestamptz,expira_em timestamptz,editado_em timestamptz,lido boolean,tipo text,exige_confirmacao boolean,confirmado_em timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH v AS (SELECT a.id,a.titulo,a.mensagem,p.nome,a.publicar_em,a.expira_em,a.editado_em,CASE WHEN a.exige_confirmacao THEN c.confirmado_em IS NOT NULL ELSE a.publicar_em<=coalesce((SELECT primeiro_acesso FROM public.profiles WHERE id=auth.uid()),'-infinity'::timestamptz) OR EXISTS(SELECT 1 FROM public.avisos_leituras l WHERE l.aviso_id=a.id AND l.usuario_id=auth.uid()) END AS lido,a.tipo,a.exige_confirmacao,c.confirmado_em FROM public.avisos a JOIN public.perfis p ON p.id=a.perfil_id LEFT JOIN public.avisos_confirmacoes c ON c.aviso_id=a.id AND c.usuario_id=auth.uid() WHERE public.aviso_disponivel(a.id) AND (NOT _so_obrigatorios OR a.exige_confirmacao) AND (_aviso_id IS NULL OR a.id=_aviso_id)) SELECT * FROM v WHERE NOT _so_nao_lidos OR NOT v.lido ORDER BY CASE WHEN _priorizar THEN v.exige_confirmacao AND NOT v.lido ELSE false END DESC,v.publicar_em DESC,v.id LIMIT least(greatest(_limite,1),100) OFFSET greatest(_deslocamento,0) $$;
CREATE OR REPLACE FUNCTION public.contar_nao_lidos() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*)::int FROM public.avisos a WHERE public.aviso_disponivel(a.id) AND CASE WHEN a.exige_confirmacao THEN NOT EXISTS(SELECT 1 FROM public.avisos_confirmacoes c WHERE c.aviso_id=a.id AND c.usuario_id=auth.uid()) ELSE a.publicar_em>coalesce((SELECT primeiro_acesso FROM public.profiles WHERE id=auth.uid()),'-infinity'::timestamptz) AND NOT EXISTS(SELECT 1 FROM public.avisos_leituras l WHERE l.aviso_id=a.id AND l.usuario_id=auth.uid()) END $$;
CREATE OR REPLACE FUNCTION public.marcar_todos_avisos_lidos() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF NOT public.is_active_user(auth.uid()) THEN RETURN 0; END IF; INSERT INTO public.avisos_leituras(aviso_id,usuario_id) SELECT a.id,auth.uid() FROM public.avisos a WHERE NOT a.exige_confirmacao AND public.aviso_vigente(a.publicar_em,a.expira_em,a.arquivado_em) ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.avisos_enviados_confirmacao() RETURNS TABLE(id uuid,titulo text,mensagem text,perfil_id uuid,perfil_nome text,autor_id uuid,autor_nome text,publicar_em timestamptz,expira_em timestamptz,editado_em timestamptz,arquivado_em timestamptz,lidos bigint,ativos bigint,tipo text,exige_confirmacao boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.titulo,a.mensagem,a.perfil_id,p.nome,a.autor_id,coalesce(nullif(pr.full_name,''),pr.email,''),a.publicar_em,a.expira_em,a.editado_em,a.arquivado_em,CASE WHEN a.exige_confirmacao THEN (SELECT count(*) FROM public.avisos_confirmacoes c JOIN public.profiles u ON u.id=c.usuario_id AND u.is_active WHERE c.aviso_id=a.id) ELSE (SELECT count(*) FROM public.avisos_leituras l JOIN public.profiles u ON u.id=l.usuario_id AND u.is_active WHERE l.aviso_id=a.id) END,(SELECT count(*) FROM public.profiles WHERE is_active),a.tipo,a.exige_confirmacao FROM public.avisos a JOIN public.perfis p ON p.id=a.perfil_id LEFT JOIN public.profiles pr ON pr.id=a.autor_id WHERE public.gere_aviso(a.autor_id,a.perfil_id) ORDER BY a.publicar_em DESC LIMIT 200 $$;
CREATE OR REPLACE FUNCTION public.acompanhamento_aviso(_aviso_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE resultado jsonb; BEGIN
IF NOT public.tem_permissao('avisos.confirmacao') OR NOT EXISTS(SELECT 1 FROM public.avisos a WHERE a.id=_aviso_id AND a.exige_confirmacao AND public.gere_aviso(a.autor_id,a.perfil_id)) THEN RAISE EXCEPTION 'Sem permissão para acompanhar este aviso'; END IF;
SELECT jsonb_build_object('titulo',a.titulo,'pessoas',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'nome',coalesce(nullif(p.full_name,''),p.email),'confirmado_em',c.confirmado_em) ORDER BY p.full_name,p.email) FROM public.profiles p LEFT JOIN public.avisos_confirmacoes c ON c.usuario_id=p.id AND c.aviso_id=a.id WHERE p.is_active),'[]'::jsonb)) INTO resultado FROM public.avisos a WHERE a.id=_aviso_id; RETURN resultado; END $$;
REVOKE ALL ON FUNCTION public.confirmar_leitura_aviso(uuid),public.acompanhamento_aviso(uuid),public.listar_avisos_confirmacao(boolean,integer,integer,boolean,uuid,boolean),public.avisos_enviados_confirmacao() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.confirmar_leitura_aviso(uuid),public.acompanhamento_aviso(uuid),public.listar_avisos_confirmacao(boolean,integer,integer,boolean,uuid,boolean),public.avisos_enviados_confirmacao(),public.aviso_disponivel(uuid) TO authenticated;
COMMENT ON TABLE public.avisos_confirmacoes IS 'Ciência explícita por colaborador; leituras automáticas e coletivas nunca confirmam avisos obrigatórios.';